import{_ as t,o as a,c as s,ao as o}from"./chunks/framework.B7UvRKha.js";const w=JSON.parse('{"title":"The project chat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat.md","filePath":"guide/chat.md","lastUpdated":null}'),h={name:"guide/chat.md"};function n(r,e,d,i,l,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="The-project-chat" tabindex="-1">The project chat <a class="header-anchor" href="#The-project-chat" aria-label="Permalink to &quot;The project chat {#The-project-chat}&quot;">​</a></h1><p>The Chat drawer (<code>Ctrl+Shift+K</code>) shows the messages of one Slack channel: the channel the selected row&#39;s folder maps to. The records the window holds are listed oldest first, and the newest sits at the bottom. The view follows the newest, so a message that arrives takes the bottom line and lifts the rest. An empty channel shows <code>no messages</code>.</p><p>To read older messages, scroll up: PageUp and PageDown move a third of the drawer, Alt+Up, Alt+Down and the mouse wheel one line. A reader scrolled up stays where they are: a message that arrives, is edited or is deleted does not move the view, and a message deleted at the reader&#39;s place stays there as <code>(message deleted)</code>; the next one takes the place only when a new snapshot or the trim drops it. <code>End</code> (<code>chat.latest</code>) returns to the newest and follows it again, and scrolling down to the newest does the same. Two cases move the view: once the drawer holds its 100 newest messages, each arrival drops the oldest, so a reader on the oldest message moves up one message per arrival (until older pages can be read); and deleting or shortening the newest message can bring the newest wholly into view, which returns the reader to following. Switching to another row&#39;s channel starts at its newest.</p><p>Each message starts with its own header line: the author&#39;s name, a tag for a post that came from the drawer, a row or a bot, and the time (<code>HH:MM</code> for today, with the date for an earlier day). The text follows as typed.</p><h2 id="Which-channel" tabindex="-1">Which channel <a class="header-anchor" href="#Which-channel" aria-label="Permalink to &quot;Which channel {#Which-channel}&quot;">​</a></h2><p>The hub&#39;s <code>chat.toml</code> maps a folder to a channel; a row whose folder is mapped shows that channel. How the mapping is written is in <a href="/ship-of-tools/dev/ref/config#chat.toml-and-chat-secrets.toml">the chat configuration</a>. The drawer follows the selected row. Its title is <code>chat · &lt;channel id&gt;</code> (the id shows only while a channel is watched) followed by what the drawer is waiting for or why it shows nothing:</p><table tabindex="0"><thead><tr><th style="text-align:right;">the title says</th><th style="text-align:right;">meaning</th><th style="text-align:right;">asked again</th></tr></thead><tbody><tr><td style="text-align:right;"><code>waiting for this row&#39;s listing</code></td><td style="text-align:right;">the window has not listed the selected row yet</td><td style="text-align:right;">every frame</td></tr><tr><td style="text-align:right;"><code>not connected</code></td><td style="text-align:right;">the row&#39;s computer is not connected</td><td style="text-align:right;">when it connects</td></tr><tr><td style="text-align:right;"><code>reading…</code></td><td style="text-align:right;">the hub is being asked, or the channel is being read</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;">(nothing after the channel)</td><td style="text-align:right;">the channel was read whole</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>the row&#39;s folder maps to no channel</code></td><td style="text-align:right;">the folder is not in <code>chat.toml</code></td><td style="text-align:right;">at a link change or another row</td></tr><tr><td style="text-align:right;"><code>the hub has no usable chat configuration</code></td><td style="text-align:right;"><code>chat.toml</code> is missing or invalid; the hub&#39;s daemon log says why</td><td style="text-align:right;">at a link change</td></tr><tr><td style="text-align:right;"><code>the chat runs on the hub, not on &lt;host&gt;</code></td><td style="text-align:right;">the row&#39;s computer is not the hub</td><td style="text-align:right;">at a link change</td></tr><tr><td style="text-align:right;"><code>the row is gone or was replaced</code></td><td style="text-align:right;">the row&#39;s id changed</td><td style="text-align:right;">when the listing gives the row a new id, or at a link change</td></tr><tr><td style="text-align:right;"><code>the hub could not answer: &lt;reason&gt;</code></td><td style="text-align:right;">the hub refused for another reason</td><td style="text-align:right;">after a minute</td></tr><tr><td style="text-align:right;"><code>this daemon has no chat: update it</code></td><td style="text-align:right;">the row&#39;s daemon is too old</td><td style="text-align:right;">at a link change</td></tr><tr><td style="text-align:right;"><code>the hub&#39;s chat service is not running</code></td><td style="text-align:right;">the hub&#39;s log says why</td><td style="text-align:right;">each minute</td></tr><tr><td style="text-align:right;"><code>not up to date: &lt;reason&gt;</code></td><td style="text-align:right;">the channel could not be read whole (<code>no snapshot</code> when the hub never answered)</td><td style="text-align:right;">each minute</td></tr><tr><td style="text-align:right;"><code>the row is gone or was replaced</code>, <code>the row now maps to another channel</code> or <code>the row&#39;s folder maps to no channel</code>, after the channel</td><td style="text-align:right;">the hub refused the watch for good</td><td style="text-align:right;">at a row or link change</td></tr></tbody></table><h2 id="Markup-shows-as-markup" tabindex="-1">Markup shows as markup <a class="header-anchor" href="#Markup-shows-as-markup" aria-label="Permalink to &quot;Markup shows as markup {#Markup-shows-as-markup}&quot;">​</a></h2><p>A message is shown as its poster typed it. Slack&#39;s markup, such as a mention or a link, is shown as the markup text in its own color and is not rendered: a link is not clickable and a mention is not replaced by a name. Text that looks like a header inside a message stays body text.</p><h2 id="Deleted-messages" tabindex="-1">Deleted messages <a class="header-anchor" href="#Deleted-messages" aria-label="Permalink to &quot;Deleted messages {#Deleted-messages}&quot;">​</a></h2><p>A message deleted while the drawer watches stays in its place, with its author, time and origin, and reads <code>(message deleted)</code>. It counts toward the 100 messages the drawer keeps. A new snapshot (the window reads one after any loss of the chat feed) drops it, since the snapshot holds only what Slack still has.</p><h2 id="When-Slack-is-unreachable" tabindex="-1">When Slack is unreachable <a class="header-anchor" href="#When-Slack-is-unreachable" aria-label="Permalink to &quot;When Slack is unreachable {#When-Slack-is-unreachable}&quot;">​</a></h2><p>The title does not show the state of the Slack connection. A socket outage shows only when it costs a snapshot, as <code>not up to date</code>. The drawer keeps the records it holds until a new snapshot replaces them. <code>no messages</code> appears only for a channel that was read whole and holds none.</p><h2 id="Not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#Not-yet" aria-label="Permalink to &quot;Not yet {#Not-yet}&quot;">​</a></h2><p>Posting from the drawer, older pages of history, threads and sharing a selection with the agent are not built yet. Each arrives with its own change, and this page says so when it does.</p>',15)])])}const p=t(h,[["render",n]]);export{w as __pageData,p as default};
